cd /d/dev/ab-tasks/chessjs-qwen-med-r2 && node -e "
require('tsx/cjs');
const { Chess } = require('./src/chess');
// white pawn a7: advance promotion
let c = new Chess('8/P7/8/8/8/8/8/K6k w - - 0 1');
console.log('w a7 plain:', JSON.stringify(c.moves({ square: 'a7' })));
console.log('w a7 verbose:', JSON.stringify(c.moves({ square: 'a7', verbose: true }).map(m => m.san)));
// white pawn a7 with black rook on b8: advance + capture promotions
c = new Chess('8/1r6/P7/8/8/8/8/K6k w - - 0 1');
console.log('w a7 cap plain:', JSON.stringify(c.moves({ square: 'a7' })));
// black pawn a2: advance promotion
c = new Chess('k7/p7/8/8/8/8/8/K7 b - - 0 1');
console.log('b a2 plain:', JSON.stringify(c.moves({ square: 'a2' })));
c = new Chess('K7/p1k5/8/8/8/8/8/1R6 b - - 0 1');
console.log('b a2 cap plain:', JSON.stringify(c.moves({ square: 'a2' })));
" 2>&1 | head -8

